variants.script:
# 1080P Variant. Removes 4K and 1080P Remux. Keeps 1080P & 720P Rresolution. Boosts x265/HEVC. Intended for slower connections (eg. Mobile Profile inside Nuvio). 

set addonName = "SELection (1080P)"
use formatter "Tamtaro (Default)"
insert after excludedStreamExpressions[expression*="https://git.tamtaro.de/ESE.json"] = {    "expression": "/*No 4K*/ resolution(streams,'2160p')",    "enabled": true  },  {    "expression": "/*No 4K Remux*/ quality(resolution(streams,'2160p'),'Bluray REMUX')",    "enabled": true  },  {    "expression": "/*No 1080P Remux*/ quality(resolution(streams,'1080p'),'Bluray REMUX')",    "enabled": true  }
insert after excludedStreamExpressions[expression*="SELect Q/R Uncached"] = {"expression": "/*Keep Unknown Quality*/ passthrough(merge(resolution(quality(merge(type(streams, 'p2p', 'http', 'usenet', 'stremio-usenet'), cached(type(streams, 'debrid'))), 'Unknown'), '2160p', '1440p', '1080p'), count(resolution(merge(type(streams, 'p2p', 'http', 'usenet', 'stremio-usenet'), cached(type(streams, 'debrid'))), '2160p')) > 0 ? [] : resolution(quality(merge(type(streams, 'p2p', 'http', 'usenet', 'stremio-usenet'), cached(type(streams, 'debrid'))), 'Unknown'), '720p'), count(resolution(merge(type(streams, 'p2p', 'http', 'usenet', 'stremio-usenet'), cached(type(streams, 'debrid'))), '2160p', '1440p', '1080p')) > 0 ? [] : resolution(quality(merge(type(streams, 'p2p', 'http', 'usenet', 'stremio-usenet'), cached(type(streams, 'debrid'))), 'Unknown'), '576p', '480p')), 'excluded')","enabled": true}
insert after excludedStreamExpressions[expression*="Final Q SELection"] =   {    "expression": "/*Keep 720p Resolution*/ passthrough(resolution(merge(type(streams, 'p2p', 'http', 'usenet', 'stremio-usenet'), cached(type(streams, 'debrid'))), '720p'), 'excluded')",    "enabled": true  }
add selOverrides {"expression": "[]", "exprNames": ["x265" ], "score": 1000, "disabled": false }

